var uc = Get<UserConnection>("UserConnection");
Guid opportunityId = Get<Guid>("OpportunityId");
const int CandidateCap = 60;
const int LeadTimeLimitWeeks = 12;

// ---- Regime matrix: KS2 section 7 "Combined eligibility matrix", transcribed. ----
// Columns: cut-out, WELS, GEMS, WaterMark. Project approved and lifecycle Current apply to all families.
// The SAME table is in BP2a_DeterministicMatch.cs, BP3_ApplyVerdicts.cs, ai-studio/tests/score_adjudication.py
// and tools/import/verify.py. If KS2 section 7 changes, they all move together.
var regimes = new Dictionary<string, bool[]>(StringComparer.OrdinalIgnoreCase) {
	{ "Wall Oven",          new[] { true,  false, true,  false } },
	{ "Cooktop",            new[] { true,  false, true,  false } },
	{ "Dishwasher",         new[] { true,  true,  true,  false } },
	{ "Rangehood",          new[] { true,  false, false, false } },
	{ "Microwave",          new[] { true,  false, false, false } },
	{ "Basin",              new[] { false, false, false, true  } },
	{ "Toilet Suite",       new[] { false, true,  false, true  } },
	{ "Basin Mixer",        new[] { false, true,  false, true  } },
	{ "Shower Set",         new[] { false, true,  false, true  } },
	{ "Kitchen Sink Mixer", new[] { false, true,  false, true  } }
};

Func<Entity, string, string> str = (e, c) => (e.GetTypedColumnValue<string>(c) ?? string.Empty).Trim();

// ---- 1. Pending lines, in line order ----
var lineEsq = new EntitySchemaQuery(uc.EntitySchemaManager, "SPAIScheduleLine");
lineEsq.PrimaryQueryColumn.IsAlwaysSelect = true;
var lc = new Dictionary<string, string>();
foreach (string c in new[] { "SPAILineNumber", "SPAIItemCode", "SPAIIsAlternative", "SPAIRoomType.Name", "SPAIUnitTier.Name",
		"SPAISpecifiedText", "SPAISpecifiedBrand", "SPAISpecifiedModel", "SPAISpecifiedFinish", "SPAIQuantity",
		"SPAIRequiredCutoutW", "SPAIRequiredCutoutH", "SPAIRequiredCutoutD", "SPAIScheduleNotes", "SPAIResolvedBy", "ModifiedOn" }) {
	lc[c] = lineEsq.AddColumn(c).Name;
}
lineEsq.Filters.Add(lineEsq.CreateFilterWithParameters(FilterComparisonType.Equal, "SPAIOpportunity", opportunityId));
lineEsq.Filters.Add(lineEsq.CreateFilterWithParameters(FilterComparisonType.Equal, "SPAILineStatus.Name", "Pending"));
var lines = new List<Entity>();
int claimedElsewhere = 0;
DateTime claimCutoff = uc.CurrentUser.GetCurrentDateTime().AddMinutes(-15);
foreach (Entity pending in lineEsq.GetEntityCollection(uc)) {
	bool claimed = (pending.GetTypedColumnValue<string>(lc["SPAIResolvedBy"]) ?? string.Empty).Trim() == "Adjudicating"
		&& pending.GetTypedColumnValue<DateTime>(lc["ModifiedOn"]) > claimCutoff;
	if (claimed) {
		claimedElsewhere++;
		continue;
	}
	lines.Add(pending);
}
// Claim what this run will send, before anything else happens.
EntitySchema claimSchema = uc.EntitySchemaManager.GetInstanceByName("SPAIScheduleLine");
foreach (Entity pending in lines) {
	Entity claim = claimSchema.CreateEntity(uc);
	if (claim.FetchFromDB(pending.PrimaryColumnValue)) {
		claim.SetColumnValue("SPAIResolvedBy", "Adjudicating");
		claim.Save(false);
	}
}
lines.Sort((a, b) => a.GetTypedColumnValue<int>(lc["SPAILineNumber"]).CompareTo(b.GetTypedColumnValue<int>(lc["SPAILineNumber"])));
Set("PendingLineCount", lines.Count);
if (lines.Count == 0) {
	// Nothing to adjudicate: no AI call is made (the gateway after this task skips it). The Opportunity moves on
	// here only if nothing else is being assessed, and the AI call count is never lowered.
	Entity opportunity = uc.EntitySchemaManager.GetInstanceByName("Opportunity").CreateEntity(uc);
	if (claimedElsewhere == 0 && opportunity.FetchFromDB(opportunityId)) {
		var statusByName = new Dictionary<string, Guid>(StringComparer.OrdinalIgnoreCase);
		var statusEsq = new EntitySchemaQuery(uc.EntitySchemaManager, "SPAIAdjudicationStatus");
		statusEsq.PrimaryQueryColumn.IsAlwaysSelect = true;
		string statusNameCol = statusEsq.AddColumn("Name").Name;
		foreach (Entity status in statusEsq.GetEntityCollection(uc)) {
			statusByName[(status.GetTypedColumnValue<string>(statusNameCol) ?? string.Empty).Trim()] = status.PrimaryColumnValue;
		}
		Guid current = opportunity.GetTypedColumnValue<Guid>("SPAIAdjudicationStatusId");
		if ((statusByName.ContainsKey("Sourcing") && current == statusByName["Sourcing"])
				|| (statusByName.ContainsKey("Adjudicating") && current == statusByName["Adjudicating"])) {
			opportunity.SetColumnValue("SPAIAdjudicationStatusId", statusByName["Awaiting Gate 1"]);
		}
		if (opportunity.GetTypedColumnValue<int>("SPAIAiCallCount") < 1) {
			opportunity.SetColumnValue("SPAIAiCallCount", 1);  // the extraction only; adjudication was not needed
		}
		opportunity.Save(false);
	}
	Set("UnresolvedLinesJson", "[]");
	Set("CandidateProductsJson", "[]");
	Set("SubstitutionRulesJson", "[]");
	Set("CandidateProductCodesJson", "[]");
	Set("PolicyContextJson", "{}");
	return true;
}

// ---- 2. Product loader (shared by specified-product and candidate queries) ----
var productColumns = new[] { "Code", "Name", "SPAIModelCode", "SPAIBrand.Name", "SPAIProductFamily.Name", "SPAILifecycleStatus.Name",
	"SPAIProjectApproved", "SPAICutoutWidthMm", "SPAICutoutHeightMm", "SPAICutoutDepthMm", "SPAIWelsRegistrationNo",
	"SPAIWELSRating", "SPAIGemsRegistrationNo", "SPAIEnergyStarRating", "SPAIWaterMarkCertNo", "SPAIFinish.Name",
	"SPAILeadTimeWeeks", "SPAITradeSellPrice", "SPAIWholesaleCost", "SPAISupersededBy.Code" };
Func<Action<EntitySchemaQuery>, List<Dictionary<string, object>>> loadProducts = addFilters => {
	var esq = new EntitySchemaQuery(uc.EntitySchemaManager, "Product");
	esq.PrimaryQueryColumn.IsAlwaysSelect = true;
	var map = new Dictionary<string, string>();
	foreach (string c in productColumns) {
		map[c] = esq.AddColumn(c).Name;
	}
	addFilters(esq);
	var result = new List<Dictionary<string, object>>();
	foreach (Entity e in esq.GetEntityCollection(uc)) {
		var p = new Dictionary<string, object> { { "Id", e.PrimaryColumnValue } };
		foreach (var kv in map) {
			p[kv.Key] = e.GetColumnValue(kv.Value);
		}
		result.Add(p);
	}
	return result;
};
Func<Dictionary<string, object>, string, string> ps = (p, c) => p[c] == null ? string.Empty : p[c].ToString().Trim();
Func<Dictionary<string, object>, string, int> pi = (p, c) => p[c] == null ? 0 : Convert.ToInt32(p[c]);
Func<Dictionary<string, object>, string, decimal?> pd = (p, c) => p[c] == null || Convert.ToDecimal(p[c]) == 0m ? (decimal?)null : Convert.ToDecimal(p[c]);

// ---- 3. Specified products (resolved by model code; typos and ambiguous lines resolve to none) ----
var modelCodeSet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
foreach (Entity line in lines) {
	string m = str(line, lc["SPAISpecifiedModel"]);
	if (m.Length > 0) {
		modelCodeSet.Add(m);
	}
}
var modelCodeList = new List<object>();
foreach (string m in modelCodeSet) {
	modelCodeList.Add(m);
}
object[] modelCodes = modelCodeList.ToArray();
var specified = modelCodes.Length == 0 ? new List<Dictionary<string, object>>() : loadProducts(esq =>
	esq.Filters.Add(esq.CreateFilterWithParameters(FilterComparisonType.Equal, "SPAIModelCode", modelCodes)));
var specifiedByModel = new Dictionary<string, Dictionary<string, object>>(StringComparer.OrdinalIgnoreCase);
foreach (var p in specified) {
	string m = ps(p, "SPAIModelCode");
	if (m.Length > 0 && !specifiedByModel.ContainsKey(m)) {
		specifiedByModel[m] = p;
	}
}

// ---- 4. Family per line: specified product, else "Family as written" note, else family name in the text ----
var familyNames = new List<string>(regimes.Keys);
familyNames.Sort((a, b) => b.Length.CompareTo(a.Length));  // longest first: "Basin Mixer" before "Basin"
Func<Entity, string> familyOf = line => {
	Dictionary<string, object> sp;
	if (specifiedByModel.TryGetValue(str(line, lc["SPAISpecifiedModel"]), out sp) && ps(sp, "SPAIProductFamily.Name").Length > 0) {
		return ps(sp, "SPAIProductFamily.Name");
	}
	string haystack = str(line, lc["SPAIScheduleNotes"]) + " " + str(line, lc["SPAISpecifiedText"]);
	foreach (string f in familyNames) {
		if (haystack.IndexOf(f, StringComparison.OrdinalIgnoreCase) >= 0) {
			return f;
		}
	}
	return string.Empty;
};
var lineFamily = new Dictionary<int, string>();
var familySet = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
foreach (Entity line in lines) {
	string f = familyOf(line);
	lineFamily[line.GetTypedColumnValue<int>(lc["SPAILineNumber"])] = f;
	if (f.Length > 0) {
		familySet.Add(f);
	}
}

// ---- 5. Candidate pool: families in play, lifecycle Current, project approved ----
var familyList = new List<object>();
foreach (string f in familySet) {
	familyList.Add(f);
}
object[] families = familyList.ToArray();
var pool = families.Length == 0 ? new List<Dictionary<string, object>>() : loadProducts(esq => {
	esq.Filters.Add(esq.CreateFilterWithParameters(FilterComparisonType.Equal, "SPAIProductFamily.Name", families));
	esq.Filters.Add(esq.CreateFilterWithParameters(FilterComparisonType.Equal, "SPAILifecycleStatus.Name", "Current"));
	esq.Filters.Add(esq.CreateFilterWithParameters(FilterComparisonType.Equal, "SPAIProjectApproved", true));
});

// ---- 6. Network availability for pool + specified products (available locations only) ----
var stockProductSet = new HashSet<Guid>();
foreach (var p in pool) {
	stockProductSet.Add((Guid)p["Id"]);
}
foreach (var p in specified) {
	stockProductSet.Add((Guid)p["Id"]);
}
var stockProductList = new List<object>();
foreach (Guid id in stockProductSet) {
	stockProductList.Add(id);
}
object[] stockProductIds = stockProductList.ToArray();
var available = new Dictionary<Guid, int>();
if (stockProductIds.Length > 0) {
	var stockEsq = new EntitySchemaQuery(uc.EntitySchemaManager, "SPAIStockPosition");
	string productCol = stockEsq.AddColumn("SPAIProduct").Name;
	string qtyCol = stockEsq.AddColumn("SPAIQtyAvailable").Name;
	stockEsq.Filters.Add(stockEsq.CreateFilterWithParameters(FilterComparisonType.Equal, "SPAIProduct", stockProductIds));
	stockEsq.Filters.Add(stockEsq.CreateFilterWithParameters(FilterComparisonType.Equal, "SPAILocation.SPAIIsAvailable", true));
	foreach (Entity s in stockEsq.GetEntityCollection(uc)) {
		Guid id = s.GetTypedColumnValue<Guid>(productCol + "Id");
		available[id] = (available.ContainsKey(id) ? available[id] : 0) + s.GetTypedColumnValue<int>(qtyCol);
	}
}
Func<Dictionary<string, object>, int> stockOf = p => available.ContainsKey((Guid)p["Id"]) ? available[(Guid)p["Id"]] : 0;

// ---- 7. Floor per (line, product), diagnostics, and the deterministic pre-rank ----
var eligibleByLine = new Dictionary<int, List<Dictionary<string, object>>>();
var lineNumbers = new List<int>();
var unresolved = new JArray();
foreach (Entity line in lines) {
	int n = line.GetTypedColumnValue<int>(lc["SPAILineNumber"]);
	lineNumbers.Add(n);
	string family = lineFamily[n];
	bool[] r;
	if (!regimes.TryGetValue(family, out r)) {
		r = new[] { true, true, true, true };  // unknown family: every regime applies, nothing can slip through
	}
	int w = line.GetTypedColumnValue<int>(lc["SPAIRequiredCutoutW"]);
	int h = line.GetTypedColumnValue<int>(lc["SPAIRequiredCutoutH"]);
	int d = line.GetTypedColumnValue<int>(lc["SPAIRequiredCutoutD"]);
	int qty = line.GetTypedColumnValue<int>(lc["SPAIQuantity"]);
	string finish = str(line, lc["SPAISpecifiedFinish"]);
	Dictionary<string, object> sp;
	specifiedByModel.TryGetValue(str(line, lc["SPAISpecifiedModel"]), out sp);
	decimal? specWels = sp == null ? null : pd(sp, "SPAIWELSRating");
	decimal? specEnergy = sp == null ? null : pd(sp, "SPAIEnergyStarRating");

	var familyPool = new List<Dictionary<string, object>>();
	foreach (var p in pool) {
		if (string.Equals(ps(p, "SPAIProductFamily.Name"), family, StringComparison.OrdinalIgnoreCase)) {
			familyPool.Add(p);
		}
	}
	int cutoutFit = 0, cutoutFitFloorFail = 0;
	var eligible = new List<Dictionary<string, object>>();
	foreach (var p in familyPool) {
		bool fits = !r[0] || (pi(p, "SPAICutoutWidthMm") == w && pi(p, "SPAICutoutHeightMm") == h && pi(p, "SPAICutoutDepthMm") == d);
		if (!fits) {
			continue;
		}
		cutoutFit++;
		bool wels = !r[1] || (ps(p, "SPAIWelsRegistrationNo").Length > 0 && (specWels == null || (pd(p, "SPAIWELSRating") ?? 0m) >= specWels));
		bool gems = !r[2] || (ps(p, "SPAIGemsRegistrationNo").Length > 0 && (specEnergy == null || (pd(p, "SPAIEnergyStarRating") ?? 0m) >= specEnergy));
		bool waterMark = !r[3] || ps(p, "SPAIWaterMarkCertNo").Length > 0;
		if (wels && gems && waterMark) {
			eligible.Add(p);
		} else {
			cutoutFitFloorFail++;
		}
	}
	// Pre-rank: compliance headroom, then availability within lead time, then availability, then finish
	// match, then product code for a stable order. Margin is NOT an input.
	Func<Dictionary<string, object>, decimal> headroom = p =>
		(specWels.HasValue ? (pd(p, "SPAIWELSRating") ?? 0m) - specWels.Value : 0m)
		+ (specEnergy.HasValue ? (pd(p, "SPAIEnergyStarRating") ?? 0m) - specEnergy.Value : 0m);
	Func<Dictionary<string, object>, bool> inTime = p => stockOf(p) >= qty && pi(p, "SPAILeadTimeWeeks") <= LeadTimeLimitWeeks;
	Func<Dictionary<string, object>, bool> inStock = p => stockOf(p) >= qty;
	Func<Dictionary<string, object>, bool> finishMatch = p => string.Equals(ps(p, "SPAIFinish.Name"), finish, StringComparison.OrdinalIgnoreCase);
	eligible.Sort((a, b) => {
		int cmp = headroom(b).CompareTo(headroom(a));
		if (cmp == 0) { cmp = inTime(b).CompareTo(inTime(a)); }
		if (cmp == 0) { cmp = inStock(b).CompareTo(inStock(a)); }
		if (cmp == 0) { cmp = finishMatch(b).CompareTo(finishMatch(a)); }
		if (cmp == 0) { cmp = string.CompareOrdinal(ps(a, "Code"), ps(b, "Code")); }
		return cmp;
	});
	eligibleByLine[n] = eligible;

	unresolved.Add(new JObject {
		["lineNumber"] = n,
		["itemRef"] = str(line, lc["SPAIItemCode"]),
		["isAlternate"] = line.GetTypedColumnValue<bool>(lc["SPAIIsAlternative"]),
		["productFamily"] = family,
		["roomType"] = str(line, lc["SPAIRoomType.Name"]),
		["unitTier"] = str(line, lc["SPAIUnitTier.Name"]),
		["specifiedText"] = str(line, lc["SPAISpecifiedText"]),
		["specifiedBrand"] = str(line, lc["SPAISpecifiedBrand"]),
		["specifiedModel"] = str(line, lc["SPAISpecifiedModel"]),
		["specifiedFinish"] = finish,
		["quantity"] = qty,
		["cutoutW"] = w, ["cutoutH"] = h, ["cutoutD"] = d,
		["notes"] = str(line, lc["SPAIScheduleNotes"]),
		["regimes"] = new JObject { ["cutout"] = r[0], ["wels"] = r[1], ["gems"] = r[2], ["waterMark"] = r[3] },
		["specifiedProduct"] = sp == null ? (JToken)JValue.CreateNull() : new JObject {
			["productCode"] = ps(sp, "Code"),
			["lifecycleStatus"] = ps(sp, "SPAILifecycleStatus.Name"),
			["supersededByCode"] = ps(sp, "SPAISupersededBy.Code"),
			["leadTimeWeeks"] = pi(sp, "SPAILeadTimeWeeks"),
			["welsRating"] = specWels.HasValue ? (JToken)specWels.Value : JValue.CreateNull(),
			["energyStarRating"] = specEnergy.HasValue ? (JToken)specEnergy.Value : JValue.CreateNull(),
			["networkQtyAvailable"] = stockOf(sp)
		},
		["floorDiagnostics"] = new JObject {
			["familyCandidates"] = familyPool.Count, ["cutoutFit"] = cutoutFit,
			["cutoutFitFloorFail"] = cutoutFitFloorFail, ["eligible"] = eligible.Count
		}
	});
}
lineNumbers.Sort();
// Pre-rank position (1-based) of a product code on a line, or 0 when it is not eligible there.
Func<int, string, int> rankOn = (n, code) => {
	var list = eligibleByLine[n];
	for (int i = 0; i < list.Count; i++) {
		if (ps(list[i], "Code") == code) {
			return i + 1;
		}
	}
	return 0;
};

// ---- 8. Substitution rules for the specified products; their eligible targets are always kept ----
var specifiedIdList = new List<object>();
foreach (var p in specified) {
	specifiedIdList.Add(p["Id"]);
}
object[] specifiedIds = specifiedIdList.ToArray();
var rules = new JArray();
var forced = new HashSet<string>(StringComparer.Ordinal);
if (specifiedIds.Length > 0) {
	var ruleEsq = new EntitySchemaQuery(uc.EntitySchemaManager, "SPAISubstitutionRule");
	string codeCol = ruleEsq.AddColumn("SPAIRuleCode").Name;
	string fromCol = ruleEsq.AddColumn("SPAIFromProduct.Code").Name;
	string toCol = ruleEsq.AddColumn("SPAIToProduct.Code").Name;
	string basisCol = ruleEsq.AddColumn("SPAIEquivalenceBasis").Name;
	string finishCol = ruleEsq.AddColumn("SPAIFinishMatch").Name;
	ruleEsq.Filters.Add(ruleEsq.CreateFilterWithParameters(FilterComparisonType.Equal, "SPAIFromProduct", specifiedIds));
	ruleEsq.Filters.Add(ruleEsq.CreateFilterWithParameters(FilterComparisonType.Equal, "SPAIIsActive", true));
	foreach (Entity rule in ruleEsq.GetEntityCollection(uc)) {
		string to = str(rule, toCol);
		var targetLines = new JArray();
		foreach (int n in lineNumbers) {
			if (rankOn(n, to) > 0) {
				targetLines.Add(n);
			}
		}
		if (targetLines.Count > 0) {
			forced.Add(to);
		}
		rules.Add(new JObject {
			["ruleCode"] = str(rule, codeCol), ["fromProductCode"] = str(rule, fromCol), ["toProductCode"] = to,
			["equivalenceBasis"] = str(rule, basisCol), ["finishMatch"] = rule.GetTypedColumnValue<bool>(finishCol),
			["targetEligibleForLines"] = targetLines
		});
	}
}

// ---- 9. Cap at 60: rule targets first, then round-robin by pre-rank so every line keeps its best ----
var selected = new List<string>(forced);
selected.Sort(StringComparer.Ordinal);
var selectedSet = new HashSet<string>(selected, StringComparer.Ordinal);
int depth = 0;
while (selected.Count < CandidateCap) {
	bool anyLeft = false;
	foreach (int n in lineNumbers) {
		var list = eligibleByLine[n];
		if (list.Count <= depth) {
			continue;
		}
		anyLeft = true;
		string code = ps(list[depth], "Code");
		if (selected.Count < CandidateCap && !selectedSet.Contains(code)) {
			selected.Add(code);
			selectedSet.Add(code);
		}
	}
	if (!anyLeft) {
		break;
	}
	depth++;
}
var byCode = new Dictionary<string, Dictionary<string, object>>(StringComparer.Ordinal);
foreach (var p in pool) {
	string code = ps(p, "Code");
	if (!byCode.ContainsKey(code)) {
		byCode[code] = p;
	}
}
Func<decimal?, JToken> num = v => v.HasValue ? (JToken)v.Value : JValue.CreateNull();
var candidates = new List<JObject>();
var bestRank = new Dictionary<string, int>(StringComparer.Ordinal);
foreach (string code in selected) {
	var p = byCode[code];
	decimal sell = p["SPAITradeSellPrice"] == null ? 0m : Convert.ToDecimal(p["SPAITradeSellPrice"]);
	decimal cost = p["SPAIWholesaleCost"] == null ? 0m : Convert.ToDecimal(p["SPAIWholesaleCost"]);
	var eligibleLines = new JArray();
	int best = int.MaxValue;
	foreach (int n in lineNumbers) {
		int rank = rankOn(n, code);
		if (rank > 0) {
			eligibleLines.Add(new JObject { ["lineNumber"] = n, ["preRank"] = rank });
			if (rank < best) {
				best = rank;
			}
		}
	}
	bestRank[code] = best;
	candidates.Add(new JObject {
		["productCode"] = code, ["name"] = ps(p, "Name"), ["modelCode"] = ps(p, "SPAIModelCode"), ["brand"] = ps(p, "SPAIBrand.Name"),
		["productFamily"] = ps(p, "SPAIProductFamily.Name"), ["lifecycleStatus"] = ps(p, "SPAILifecycleStatus.Name"),
		["projectApproved"] = true,
		["cutoutW"] = pi(p, "SPAICutoutWidthMm"), ["cutoutH"] = pi(p, "SPAICutoutHeightMm"), ["cutoutD"] = pi(p, "SPAICutoutDepthMm"),
		["welsRegistrationNo"] = ps(p, "SPAIWelsRegistrationNo"), ["welsRating"] = num(pd(p, "SPAIWELSRating")),
		["gemsRegistrationNo"] = ps(p, "SPAIGemsRegistrationNo"), ["energyStarRating"] = num(pd(p, "SPAIEnergyStarRating")),
		["waterMarkCertNo"] = ps(p, "SPAIWaterMarkCertNo"), ["finish"] = ps(p, "SPAIFinish.Name"),
		["leadTimeWeeks"] = pi(p, "SPAILeadTimeWeeks"),
		// Disclosed for the human reviewer. Never a sort key here, never a ranking input for the model.
		["marginPct"] = sell == 0m ? (JToken)JValue.CreateNull() : Math.Round((sell - cost) / sell * 100m, 1),
		["eligibleLines"] = eligibleLines
	});
}
candidates.Sort((a, b) => {
	int cmp = bestRank[(string)a["productCode"]].CompareTo(bestRank[(string)b["productCode"]]);
	return cmp != 0 ? cmp : string.CompareOrdinal((string)a["productCode"], (string)b["productCode"]);
});

Set("UnresolvedLinesJson", unresolved.ToString(Newtonsoft.Json.Formatting.None));
Set("CandidateProductsJson", new JArray(candidates).ToString(Newtonsoft.Json.Formatting.None));
Set("SubstitutionRulesJson", rules.ToString(Newtonsoft.Json.Formatting.None));
Set("CandidateProductCodesJson", new JArray(selected).ToString(Newtonsoft.Json.Formatting.None));
Set("PolicyContextJson", new JObject {
	["policy"] = "Meridian Substitution Governance Policy v1.0 (knowledge source KS1)",
	["leadTimeLimitWeeks"] = LeadTimeLimitWeeks,
	["candidateCap"] = CandidateCap,
	["regimeSource"] = "KS2 Regulatory Compliance Reference, section 7"
}.ToString(Newtonsoft.Json.Formatting.None));
return true;

var uc = Get<UserConnection>("UserConnection");
var codeList = new List<object>();
foreach (JToken t in JArray.Parse(Get<string>("CandidateProductCodesJson") ?? "[]")) {
	codeList.Add((string)t);
}
object[] codes = codeList.ToArray();
var stock = new JArray();
if (codes.Length > 0) {
	var esq = new EntitySchemaQuery(uc.EntitySchemaManager, "SPAIStockPosition");
	var c = new Dictionary<string, string>();
	foreach (string column in new[] { "SPAIProduct.Code", "SPAILocation.SPAICode", "SPAILocation.SPAIName",
			"SPAILocation.SPAILocationType.Name", "SPAILocation.SPAISourcingRank", "SPAIQtyOnHand", "SPAIQtyAvailable",
			"SPAINextInboundQty", "SPAINextInboundDate" }) {
		c[column] = esq.AddColumn(column).Name;
	}
	esq.Filters.Add(esq.CreateFilterWithParameters(FilterComparisonType.Equal, "SPAIProduct.Code", codes));
	esq.Filters.Add(esq.CreateFilterWithParameters(FilterComparisonType.Equal, "SPAILocation.SPAIIsAvailable", true));
	var rows = new List<Entity>();
	foreach (Entity e in esq.GetEntityCollection(uc)) {
		rows.Add(e);
	}
	// Product code, then sourcing rank: a stable order for the model and the trace.
	rows.Sort((a, b) => {
		int cmp = string.CompareOrdinal(a.GetTypedColumnValue<string>(c["SPAIProduct.Code"]),
			b.GetTypedColumnValue<string>(c["SPAIProduct.Code"]));
		return cmp != 0 ? cmp : a.GetTypedColumnValue<int>(c["SPAILocation.SPAISourcingRank"])
			.CompareTo(b.GetTypedColumnValue<int>(c["SPAILocation.SPAISourcingRank"]));
	});
	foreach (Entity e in rows) {
		// Gap 3 (token spend): a row with nothing available and nothing inbound cannot change a decision.
		if (e.GetTypedColumnValue<int>(c["SPAIQtyAvailable"]) <= 0 && e.GetTypedColumnValue<int>(c["SPAINextInboundQty"]) <= 0) {
			continue;
		}
		DateTime inbound = e.GetTypedColumnValue<DateTime>(c["SPAINextInboundDate"]);
		stock.Add(new JObject {
			["productCode"] = e.GetTypedColumnValue<string>(c["SPAIProduct.Code"]),
			["locationCode"] = e.GetTypedColumnValue<string>(c["SPAILocation.SPAICode"]),
			["locationName"] = e.GetTypedColumnValue<string>(c["SPAILocation.SPAIName"]),
			["locationType"] = e.GetTypedColumnValue<string>(c["SPAILocation.SPAILocationType.Name"]),
			["sourcingRank"] = e.GetTypedColumnValue<int>(c["SPAILocation.SPAISourcingRank"]),
			["qtyOnHand"] = e.GetTypedColumnValue<int>(c["SPAIQtyOnHand"]),
			["qtyAvailable"] = e.GetTypedColumnValue<int>(c["SPAIQtyAvailable"]),
			["nextInboundQty"] = e.GetTypedColumnValue<int>(c["SPAINextInboundQty"]),
			["nextInboundDate"] = inbound == DateTime.MinValue ? string.Empty : inbound.ToString("yyyy-MM-dd")
		});
	}
}
Set("NetworkStockJson", stock.ToString(Newtonsoft.Json.Formatting.None));
Func<string, JToken> part = name => JToken.Parse(Get<string>(name) ?? "null");
Set("AdjudicatorRequestJson", new JObject {
	["unresolvedLines"] = part("UnresolvedLinesJson"),
	["candidateProducts"] = part("CandidateProductsJson"),
	["substitutionRules"] = part("SubstitutionRulesJson"),
	["networkStock"] = stock,
	["policyContext"] = part("PolicyContextJson")
}.ToString(Newtonsoft.Json.Formatting.None));
return true;

var uc = Get<UserConnection>("UserConnection");
Guid opportunityId = Get<Guid>("OpportunityId");
// The skill is told to return only the JSON object, but a model reply can arrive wrapped in a
// ```json fence or a sentence. Take the outermost {...} (or [...]) and parse that. If nothing parses,
// verdicts stays empty and every pending line is escalated below with a ledger row saying why:
// a bad reply must never crash the process and leave lines silently Pending.
string rawVerdicts = (Get<string>("VerdictsJson") ?? string.Empty).Trim();
JArray verdicts = new JArray();
string parseProblem = null;
int objStart = rawVerdicts.IndexOf('{'), objEnd = rawVerdicts.LastIndexOf('}');
int arrStart = rawVerdicts.IndexOf('['), arrEnd = rawVerdicts.LastIndexOf(']');
string candidateJson = objStart >= 0 && objEnd > objStart && (arrStart < 0 || objStart < arrStart)
	? rawVerdicts.Substring(objStart, objEnd - objStart + 1)
	: (arrStart >= 0 && arrEnd > arrStart ? rawVerdicts.Substring(arrStart, arrEnd - arrStart + 1) : string.Empty);
try {
	JToken parsed = JToken.Parse(candidateJson.Length > 0 ? candidateJson : "null");
	if (parsed is JObject && parsed["verdicts"] is JArray) {
		verdicts = (JArray)parsed["verdicts"];
	} else if (parsed is JArray) {
		verdicts = (JArray)parsed;
	} else {
		parseProblem = "the Adjudicator reply contained no verdicts array";
	}
} catch (Exception parseError) {
	parseProblem = "the Adjudicator reply was not valid JSON (" + parseError.Message + ")";
}
// When the call itself failed, say so: the element's own status and error beat a parse message.
string callStatus = (Get<string>("AdjudicatorStatus") ?? string.Empty).Trim();
string callError = (Get<string>("AdjudicatorError") ?? string.Empty).Trim();
if (parseProblem != null && (callError.Length > 0 || callStatus.Length > 0)) {
	parseProblem = "the Adjudicator call returned no usable verdicts (status: "
		+ (callStatus.Length > 0 ? callStatus : "not reported")
		+ (callError.Length > 0 ? "; error: " + (callError.Length > 300 ? callError.Substring(0, 300) : callError) : string.Empty) + ")";
}
var candidateCodes = new HashSet<string>(StringComparer.Ordinal);
foreach (JToken t in JArray.Parse(Get<string>("CandidateProductCodesJson") ?? "[]")) {
	candidateCodes.Add((string)t);
}
var lineContext = new Dictionary<int, JObject>();
foreach (JToken t in JArray.Parse(Get<string>("UnresolvedLinesJson") ?? "[]")) {
	JObject l = t as JObject;
	if (l != null && l["lineNumber"] != null) {
		lineContext[(int)l["lineNumber"]] = l;
	}
}

// ---- Lookups ----
Func<string, string, Dictionary<string, Guid>> loadBy = (schemaName, column) => {
	var esq = new EntitySchemaQuery(uc.EntitySchemaManager, schemaName);
	esq.PrimaryQueryColumn.IsAlwaysSelect = true;
	string col = esq.AddColumn(column).Name;
	var map = new Dictionary<string, Guid>(StringComparer.OrdinalIgnoreCase);
	foreach (Entity e in esq.GetEntityCollection(uc)) {
		map[(e.GetTypedColumnValue<string>(col) ?? string.Empty).Trim()] = e.PrimaryColumnValue;
	}
	return map;
};
var lineStatus = loadBy("SPAILineStatus", "Name");
var decisionType = loadBy("SPAIDecisionType", "Name");
var reasonEsq = new EntitySchemaQuery(uc.EntitySchemaManager, "SPAIReasonCode");
reasonEsq.PrimaryQueryColumn.IsAlwaysSelect = true;
string reasonCodeCol = reasonEsq.AddColumn("SPAICode").Name;
string reasonHumanCol = reasonEsq.AddColumn("SPAIRequiresHuman").Name;
var reasons = new Dictionary<string, Tuple<Guid, bool>>(StringComparer.Ordinal);
foreach (Entity e in reasonEsq.GetEntityCollection(uc)) {
	reasons[(e.GetTypedColumnValue<string>(reasonCodeCol) ?? string.Empty).Trim()] =
		Tuple.Create(e.PrimaryColumnValue, e.GetTypedColumnValue<bool>(reasonHumanCol));
}
var escalationCodes = new HashSet<string> { "AMBIGUOUS_SPEC", "DIM_MISMATCH", "COMPLIANCE_FAIL", "NO_EQUIVALENT" };

// ---- Pending lines of this opportunity that this run sent to the model, keyed by line number ----
var lineEsq = new EntitySchemaQuery(uc.EntitySchemaManager, "SPAIScheduleLine");
lineEsq.PrimaryQueryColumn.IsAlwaysSelect = true;
string numCol = lineEsq.AddColumn("SPAILineNumber").Name;
lineEsq.Filters.Add(lineEsq.CreateFilterWithParameters(FilterComparisonType.Equal, "SPAIOpportunity", opportunityId));
lineEsq.Filters.Add(lineEsq.CreateFilterWithParameters(FilterComparisonType.Equal, "SPAILineStatus.Name", "Pending"));
var pendingIds = new Dictionary<int, Guid>();
foreach (Entity e in lineEsq.GetEntityCollection(uc)) {
	int pendingNumber = e.GetTypedColumnValue<int>(numCol);
	// Only the lines THIS run claimed and sent; another run may be assessing the rest.
	if (lineContext.ContainsKey(pendingNumber)) {
		pendingIds[pendingNumber] = e.PrimaryColumnValue;
	}
}

EntitySchema lineSchema = uc.EntitySchemaManager.GetInstanceByName("SPAIScheduleLine");
EntitySchema productSchema = uc.EntitySchemaManager.GetInstanceByName("Product");
EntitySchema ledgerSchema = uc.EntitySchemaManager.GetInstanceByName("SPAIDecisionLedger");
Func<string, int, string> cut = (v, max) => v == null ? string.Empty : (v.Length <= max ? v : v.Substring(0, max));
Func<Guid, object> orNull = g => g == Guid.Empty ? null : (object)g;

Action<Guid, string, string, Guid, Guid, double, string, string, string, int> writeLedger =
	(lineId, actor, type, productId, reasonId, confidence, checks, prior, next, sequence) => {
		Entity row = ledgerSchema.CreateEntity(uc);
		row.SetDefColumnValues();
		row.SetColumnValue("SPAIOpportunityId", opportunityId);
		row.SetColumnValue("SPAIScheduleLineId", orNull(lineId));
		row.SetColumnValue("SPAIDecisionTypeId", decisionType[type]);
		row.SetColumnValue("SPAIActor", cut(actor, 250));
		row.SetColumnValue("SPAIProposedProductId", orNull(productId));
		row.SetColumnValue("SPAIReasonCodeId", orNull(reasonId));
		row.SetColumnValue("SPAIConfidence", confidence);
		row.SetColumnValue("SPAIComplianceChecks", checks);
		row.SetColumnValue("SPAIPriorValue", cut(prior, 250));
		row.SetColumnValue("SPAINewValue", cut(next, 250));
		row.SetColumnValue("SPAISequence", sequence);
		row.SetColumnValue("SPAIOccurredOn", uc.CurrentUser.GetCurrentDateTime());
		row.Save(false);
	};

int resolved = 0, escalated = 0, overrides = 0;
var seen = new HashSet<int>();
foreach (JToken verdictToken in verdicts) {
	JObject v = verdictToken as JObject;
	if (v == null) {
		continue;
	}
	int n = v["lineNumber"] == null ? 0 : (int)v["lineNumber"];
	Guid lineId;
	if (!pendingIds.TryGetValue(n, out lineId) || !seen.Add(n)) {
		continue;  // not a pending line of this tender, or a duplicate verdict: never written
	}
	string modelCode = ((string)v["reasonCode"] ?? string.Empty).Trim();
	string code = modelCode;
	string selected = v["selectedProductCode"] == null || v["selectedProductCode"].Type == JTokenType.Null
		? string.Empty : ((string)v["selectedProductCode"]).Trim();
	double confidence = 0d;
	JToken confidenceToken = v["confidence"];
	if (confidenceToken != null && (confidenceToken.Type == JTokenType.Float || confidenceToken.Type == JTokenType.Integer)) {
		confidence = (double)confidenceToken;
	} else if (confidenceToken != null && confidenceToken.Type == JTokenType.String) {
		double.TryParse((string)confidenceToken, System.Globalization.NumberStyles.Float,
			System.Globalization.CultureInfo.InvariantCulture, out confidence);
	}
	bool modelHuman = v["requiresHuman"] != null && v["requiresHuman"].Type == JTokenType.Boolean && (bool)v["requiresHuman"];
	var checks = new List<string>();
	string overrideReason = null;

	if (!reasons.ContainsKey(code) || code == "EXACT" || code == "MULTI_SOURCE") {
		overrideReason = "Unknown or non-adjudicator reason code '" + modelCode + "'";
		code = "NO_EQUIVALENT";
	}
	if (escalationCodes.Contains(code) && selected.Length > 0) {
		checks.Add("escalation code carries no product: '" + selected + "' discarded");
		selected = string.Empty;
	}

	Entity product = null;
	if (selected.Length > 0) {
		bool inSet = candidateCodes.Contains(selected);
		checks.Add("closed set: " + (inSet ? "PASS" : "FAIL"));
		product = productSchema.CreateEntity(uc);
		bool exists = inSet && product.FetchFromDB("Code", selected);
		checks.Add("product exists: " + (exists ? "PASS" : "FAIL"));
		if (!exists) {
			overrideReason = "Returned code '" + selected + "' is not in the supplied candidate set or not a Product (closed-set validation)";
			code = "NO_EQUIVALENT";
			product = null;
		}
	}

	JObject ctx;
	lineContext.TryGetValue(n, out ctx);
	if (product != null && ctx != null) {
		// Floor re-verification from the database record, not from the model's claims.
		JObject regime = (JObject)ctx["regimes"];
		JToken spec = ctx["specifiedProduct"];
		Func<string, decimal> dec = col => product.GetTypedColumnValue<decimal>(col);
		decimal? specWels = spec != null && spec.Type == JTokenType.Object && spec["welsRating"].Type != JTokenType.Null ? (decimal?)spec["welsRating"] : null;
		decimal? specEnergy = spec != null && spec.Type == JTokenType.Object && spec["energyStarRating"].Type != JTokenType.Null ? (decimal?)spec["energyStarRating"] : null;
		// Each check records what was found, and "n/a" when the regime does not apply (same wording as BP2a).
		string familyText = ctx["productFamily"] == null || ((string)ctx["productFamily"]).Length == 0
			? "this product family" : (string)ctx["productFamily"];
		var failed = new List<string>();
		Action<string, bool, string, string> check = (rule, passed, found, failure) => {
			checks.Add(rule + ": " + (passed ? "PASS" : "FAIL") + " (" + (passed ? found : failure) + ")");
			if (!passed) {
				failed.Add(rule + " " + failure);
			}
		};
		Action<string, string> notApplicable = (rule, why) => checks.Add(rule + ": n/a (" + why + ")");
		Func<string, string> text = col => (product.GetTypedColumnValue<string>(col) ?? string.Empty).Trim();

		var lifecycleEsq = new EntitySchemaQuery(uc.EntitySchemaManager, "Product");
		string lifecycleCol = lifecycleEsq.AddColumn("SPAILifecycleStatus.Name").Name;
		Entity lifecycleRow = lifecycleEsq.GetEntity(uc, product.PrimaryColumnValue);
		string lifecycle = lifecycleRow == null ? string.Empty : (lifecycleRow.GetTypedColumnValue<string>(lifecycleCol) ?? string.Empty).Trim();
		check("lifecycle", lifecycle == "Current", "Current", "is " + (lifecycle.Length > 0 ? lifecycle : "not set") + ", must be Current");
		check("project approval", product.GetTypedColumnValue<bool>("SPAIProjectApproved"), "approved", "not given");
		int pw = product.GetTypedColumnValue<int>("SPAICutoutWidthMm");
		int ph = product.GetTypedColumnValue<int>("SPAICutoutHeightMm");
		int pdp = product.GetTypedColumnValue<int>("SPAICutoutDepthMm");
		int w = (int)ctx["cutoutW"], h = (int)ctx["cutoutH"], d = (int)ctx["cutoutD"];
		if ((bool)regime["cutout"]) {
			string productCut = string.Format("{0}x{1}x{2}", pw, ph, pdp);
			check("cut-out", pw == w && ph == h && pdp == d, productCut + " matches specified",
				string.Format("{0} does not match specified {1}x{2}x{3}", productCut, w, h, d));
		} else {
			notApplicable("cut-out", familyText + " has no cut-out rule");
		}
		if ((bool)regime["wels"]) {
			string reg = text("SPAIWelsRegistrationNo");
			decimal rating = dec("SPAIWELSRating");
			bool ratingOk = !specWels.HasValue || rating >= specWels.Value;
			check("WELS", reg.Length > 0 && ratingOk,
				"registered " + reg + (specWels.HasValue ? string.Format(", rating {0} >= specified {1}", rating, specWels.Value) : string.Empty),
				reg.Length == 0 ? "not registered" : string.Format("rating {0} below specified {1}", rating, specWels.GetValueOrDefault()));
		} else {
			notApplicable("WELS", familyText + " is not WELS-regulated");
		}
		if ((bool)regime["gems"]) {
			string reg = text("SPAIGemsRegistrationNo");
			decimal rating = dec("SPAIEnergyStarRating");
			bool ratingOk = !specEnergy.HasValue || rating >= specEnergy.Value;
			check("GEMS", reg.Length > 0 && ratingOk,
				"registered " + reg + (specEnergy.HasValue ? string.Format(", energy rating {0} >= specified {1}", rating, specEnergy.Value) : string.Empty),
				reg.Length == 0 ? "not registered" : string.Format("energy rating {0} below specified {1}", rating, specEnergy.GetValueOrDefault()));
		} else {
			notApplicable("GEMS", familyText + " is not GEMS-regulated");
		}
		if ((bool)regime["waterMark"]) {
			string cert = text("SPAIWaterMarkCertNo");
			check("WaterMark", cert.Length > 0, "certificate " + cert, "certificate missing");
		} else {
			notApplicable("WaterMark", familyText + " does not need WaterMark");
		}
		if (failed.Count > 0) {
			overrideReason = "Compliance floor failed on re-verification: " + string.Join("; ", failed);
			code = "COMPLIANCE_FAIL";
			product = null;
		}
	}

	var reason = reasons[code];
	bool finalHuman = modelHuman || reason.Item2 || overrideReason != null;
	checks.Add(string.Format("requiresHuman: model={0} lookup={1} override={2} final={3}",
		modelHuman, reason.Item2, overrideReason != null, finalHuman));
	string status = code == "NO_EQUIVALENT" ? "No match" : (finalHuman ? "Escalated" : "Substitution proposed");

	Entity line = lineSchema.CreateEntity(uc);
	line.FetchFromDB(lineId);
	string prior = "Pending";
	line.SetColumnValue("SPAIReasonCodeId", reason.Item1);
	line.SetColumnValue("SPAIConfidence", confidence);
	line.SetColumnValue("SPAIAdjudicationNote", (string)v["justification"] ?? string.Empty);
	line.SetColumnValue("SPAIComplianceNotes", string.Join(" ", new[] { (string)v["complianceNotes"] ?? string.Empty,
		overrideReason == null ? string.Empty : "Process override: " + overrideReason + "." }).Trim());
	line.SetColumnValue("SPAIResolvedBy", "Adjudicator");
	line.SetColumnValue("SPAILineStatusId", lineStatus[status]);
	if (product != null) {
		decimal sell = product.GetTypedColumnValue<decimal>("SPAITradeSellPrice");
		decimal cost = product.GetTypedColumnValue<decimal>("SPAIWholesaleCost");
		int qty = line.GetTypedColumnValue<int>("SPAIQuantity");
		line.SetColumnValue("SPAIMatchedProductId", product.PrimaryColumnValue);
		line.SetColumnValue("SPAIUnitCost", cost);
		line.SetColumnValue("SPAIUnitSell", sell);
		line.SetColumnValue("SPAILineTotal", sell * qty);
		line.SetColumnValue("SPAILineMarginPct", sell == 0m ? 0m : Math.Round((sell - cost) / sell * 100m, 1));
	}
	line.Save(false);

	Guid productId = product == null ? Guid.Empty : product.PrimaryColumnValue;
	string next = status + " | " + code + (product == null ? string.Empty : " | " + selected);
	Guid modelReasonId = reasons.ContainsKey(modelCode) ? reasons[modelCode].Item1 : Guid.Empty;
	writeLedger(lineId, "SPAI Adjudicator (Creatio.ai skill)", "AI adjudication",
		overrideReason == null ? productId : Guid.Empty, overrideReason == null ? reason.Item1 : modelReasonId, confidence,
		string.Join("; ", checks), prior,
		overrideReason == null ? next : "Model proposed " + modelCode + (selected.Length > 0 ? " | " + selected : string.Empty), n);
	if (overrideReason != null) {
		overrides++;
		writeLedger(lineId, "BP3 SPAIAdjudication", "Compliance rejection", Guid.Empty, reason.Item1, confidence,
			overrideReason + ". " + string.Join("; ", checks), "Model proposed " + modelCode, next, n);
	}
	if (finalHuman) {
		escalated++;
	} else if (product != null) {
		resolved++;
	}
}

// Pending lines the model returned no verdict for: escalate, never leave silently pending.
foreach (var kv in pendingIds) {
	if (seen.Contains(kv.Key)) {
		continue;
	}
	Entity line = lineSchema.CreateEntity(uc);
	line.FetchFromDB(kv.Value);
	line.SetColumnValue("SPAILineStatusId", lineStatus["Escalated"]);
	line.SetColumnValue("SPAIResolvedBy", "Adjudicator");
	string missing = parseProblem != null ? parseProblem : "the Adjudicator returned no verdict for this line";
	line.SetColumnValue("SPAIComplianceNotes", "Process override: " + missing + ".");
	line.Save(false);
	writeLedger(kv.Value, "BP3 SPAIAdjudication", "Compliance rejection", Guid.Empty, Guid.Empty, 0d,
		"No usable verdict for line " + kv.Key + " (" + missing + "); escalated to Gate 1.", "Pending", "Escalated", kv.Key);
	escalated++;
	overrides++;
}

// The Opportunity: tender-wide totals (so a re-run reports the whole tender), then Awaiting Gate 1.
Func<string, int> countByStatus = statusName => {
	var countEsq = new EntitySchemaQuery(uc.EntitySchemaManager, "SPAIScheduleLine");
	countEsq.PrimaryQueryColumn.IsAlwaysSelect = true;
	countEsq.Filters.Add(countEsq.CreateFilterWithParameters(FilterComparisonType.Equal, "SPAIOpportunity", opportunityId));
	countEsq.Filters.Add(countEsq.CreateFilterWithParameters(FilterComparisonType.Equal, "SPAILineStatus.Name", statusName));
	return countEsq.GetEntityCollection(uc).Count;
};
Entity opportunity = uc.EntitySchemaManager.GetInstanceByName("Opportunity").CreateEntity(uc);
if (opportunity.FetchFromDB(opportunityId)) {
	// A real count: the extraction in chat (1) plus every adjudication call that actually ran.
	opportunity.SetColumnValue("SPAIAiCallCount", Math.Max(1, opportunity.GetTypedColumnValue<int>("SPAIAiCallCount")) + 1);
	opportunity.SetColumnValue("SPAISubstitutionCount", countByStatus("Substitution proposed"));
	opportunity.SetColumnValue("SPAIEscalationCount", countByStatus("Escalated") + countByStatus("No match"));
	opportunity.SetColumnValue("SPAIAdjudicationStatusId", loadBy("SPAIAdjudicationStatus", "Name")["Awaiting Gate 1"]);
	opportunity.Save(false);
}
Set("ResolvedCount", resolved);
Set("EscalatedCount", escalated);
Set("OverrideCount", overrides);
return true;
